const D = { warp:.55, density:.6, energy:.7, speed:1, scale:1, swirl:.5, hue:28, x:.5, y:.5, style:'marbled-paint', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- coarse feedback field (float rgb pigment, semi-Lagrangian advection) ----
const BW = Math.max(340, Math.min(480, Math.round(width/2.8))), BH = Math.max(72, Math.round(BW * height / width));
const N = BW * BH, inw = 1 / BW, inh = 1 / BH;
if (!S.g || S.bw !== BW || S.bh !== BH) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1);
  S.bw = BW; S.bh = BH; S.seedUsed = null;
  S.r = new Float32Array(N); S.gc = new Float32Array(N); S.b = new Float32Array(N);
  S.r2 = new Float32Array(N); S.g2 = new Float32Array(N); S.b2 = new Float32Array(N);
  S.dr = new Float32Array(N); S.dg = new Float32Array(N); S.db = new Float32Array(N);
}
function h2r(h, s, v) {
  h = (((h % 360) + 360) % 360) / 60; const c = v * s, x = c * (1 - Math.abs(h % 2 - 1)), m = v - c;
  let r, g, b;
  if (h < 1) { r = c; g = x; b = 0; } else if (h < 2) { r = x; g = c; b = 0; }
  else if (h < 3) { r = 0; g = c; b = x; } else if (h < 4) { r = 0; g = x; b = c; }
  else if (h < 5) { r = x; g = 0; b = c; } else { r = c; g = 0; b = x; }
  return [r + m, g + m, b + m];
}
const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  S.hoff = fr(5); S.o1 = fr(7) * 10; S.o2 = fr(9) * 10;
  // toned colored ground (low value, gently varying) — keeps the frame filled, never empties
  for (let j = 0; j < BH; j++) for (let i = 0; i < BW; i++) {
    const idx = j * BW + i, nx = i * inw, ny = j * inh;
    const v = 0.13 + 0.07 * (0.5 + 0.5 * Math.sin((nx * 2.3 + S.o1) * 6.283) * Math.cos((ny * 1.9 + S.o2) * 6.283));
    const gh = (P.hue + S.hoff * 60 + nx * 40 - ny * 30) % 360, c = h2r(gh, 0.55, v);
    S.dr[idx] = c[0]; S.dg[idx] = c[1]; S.db[idx] = c[2];
    // prime the live field so the very first frame already carries colour edge-to-edge
    S.r[idx] = c[0] * 1.4; S.gc[idx] = c[1] * 1.4; S.b[idx] = c[2] * 1.4;
  }
}
function pal(m, hb) {
  const hr = hb / 360;
  return [0.5 + 0.5 * Math.cos(6.2831 * (m + hr)),
          0.5 + 0.5 * Math.cos(6.2831 * (m + hr + 0.33)),
          0.5 + 0.5 * Math.cos(6.2831 * (m + hr + 0.66))];
}

const style = P.style;
const T = K.t * (0.3 + P.speed * 0.5);
const cx = BW * 0.5, cy = BH * 0.5;
const fscl = 2.6 / (0.5 + P.scale);
const wpx = 0.6 + P.warp * 2.6;                         // flow smear distance (px/frame)
const swScale = (0.006 + P.swirl * 0.028) * (0.5 + P.speed * 0.6) * (0.85 + K.intensity * 0.4);
const zpx = 0.003 * (0.5 + P.speed);                    // slow feedback zoom (tunnel)
const decay = 0.93;
const amb = 0.06;                                       // continuous ground feed → never washes out / never empties
const r = S.r, gc = S.gc, b = S.b, r2 = S.r2, g2 = S.g2, b2 = S.b2, dr = S.dr, dg = S.dg, db = S.db;

// ---- advect the previous frame, add ambient ground ----
for (let j = 0; j < BH; j++) {
  for (let i = 0; i < BW; i++) {
    const idx = j * BW + i, nx = i * inw, ny = j * inh;
    const fa = Math.sin((nx * fscl + T * 0.6) * 6.2831)
             + Math.cos((ny * fscl - T * 0.45) * 6.2831)
             + 0.6 * Math.sin(((nx + ny) * fscl * 0.7 + T * 0.33) * 6.2831);
    const ang = fa * 1.9;
    const rxn = i - cx, ryn = j - cy;
    const dx = Math.cos(ang) * wpx - ryn * swScale + rxn * zpx;
    const dy = Math.sin(ang) * wpx + rxn * swScale + ryn * zpx;
    let sx = i - dx, sy = j - dy;
    let x0 = Math.floor(sx), y0 = Math.floor(sy);
    const fx = sx - x0, fy = sy - y0;
    x0 = ((x0 % BW) + BW) % BW; y0 = ((y0 % BH) + BH) % BH;
    let x1 = x0 + 1; if (x1 >= BW) x1 = 0; let y1 = y0 + 1; if (y1 >= BH) y1 = 0;
    const i00 = y0 * BW + x0, i10 = y0 * BW + x1, i01 = y1 * BW + x0, i11 = y1 * BW + x1;
    const w00 = (1 - fx) * (1 - fy), w10 = fx * (1 - fy), w01 = (1 - fx) * fy, w11 = fx * fy;
    r2[idx] = decay * (r[i00] * w00 + r[i10] * w10 + r[i01] * w01 + r[i11] * w11) + amb * dr[idx];
    g2[idx] = decay * (gc[i00] * w00 + gc[i10] * w10 + gc[i01] * w01 + gc[i11] * w11) + amb * dg[idx];
    b2[idx] = decay * (b[i00] * w00 + b[i10] * w10 + b[i01] * w01 + b[i11] * w11) + amb * db[idx];
  }
}

// ---- inject bright colored brush blobs (hue drifting on K.t) — the paint that gets smeared ----
const nB = 3 + Math.round(P.density * 5);
const kick = 0.8 + K.pulse * 0.5 + A.bass * 0.9;
const dep0 = 0.055 * (0.4 + P.density) * (0.6 + P.energy * 0.9) * kick;
const hb = (P.hue + S.hoff * 50 + K.section * 22 + K.t * 2.5) % 360;
for (let k = 0; k < nB; k++) {
  const p1 = fr(k * 3 + 1), p2 = fr(k * 3 + 2), p3 = fr(k * 3 + 3);
  const dr8 = K.t * (0.15 + 0.05 * k) * (0.5 + P.speed * 0.7);
  const bx = (P.x + 0.34 * Math.sin(dr8 + p1 * 6.283)) * BW;
  const by = (P.y + 0.34 * Math.cos(dr8 * 0.9 + p2 * 6.283)) * BH;
  const rad = Math.max(4, BW * (0.06 + p3 * 0.06) * P.scale * (0.85 + 0.35 * K.swell));
  const sig2 = rad * rad * 0.28;
  const bh = hb + p1 * 170 + (k % 2 ? 1 : -1) * K.t * (3 + P.density * 6);
  const col = h2r(bh, 0.82, 1);
  const dep = dep0 * (0.7 + p2 * 0.6);
  const x0 = Math.floor(bx - rad), x1 = Math.ceil(bx + rad), y0 = Math.floor(by - rad), y1 = Math.ceil(by + rad);
  for (let yy = y0; yy <= y1; yy++) {
    let jj = ((yy % BH) + BH) % BH;
    for (let xx = x0; xx <= x1; xx++) {
      const dxp = xx - bx, dyp = yy - by, d2 = dxp * dxp + dyp * dyp;
      if (d2 > rad * rad) continue;
      let ii = ((xx % BW) + BW) % BW;
      const f = Math.exp(-d2 / (2 * sig2)) * dep;
      const idx = jj * BW + ii;
      r2[idx] = Math.min(1.25, r2[idx] + f * col[0]);
      g2[idx] = Math.min(1.25, g2[idx] + f * col[1]);
      b2[idx] = Math.min(1.25, b2[idx] + f * col[2]);
    }
  }
}

// ---- render the field through the chosen discipline ----
const expo = 0.62 + P.energy * 0.55 + K.intensity * 0.25 + A.rms * 0.5;
const g = S.g; g.loadPixels(); const px = g.pixels;
for (let idx = 0; idx < N; idx++) {
  const rr = r2[idx], gg = g2[idx], bb = b2[idx], inten = (rr + gg + bb) * 0.3333;
  let oR, oG, oB;
  if (style === 'oil-slick') {
    const c = pal(inten * 1.5 + (rr - bb) * 1.1 + T * 0.08, hb);
    const sh = 0.32 + 0.8 * Math.min(1, inten * expo);
    oR = c[0] * sh; oG = c[1] * sh; oB = c[2] * sh;
  } else if (style === 'ember-flow') {
    const m = Math.min(1.3, inten * expo * 1.55);
    oR = Math.min(1, m * 2.3); oG = Math.min(1, Math.max(0, m * 1.9 - 0.5)); oB = Math.min(1, Math.max(0, m * 3.6 - 2.4));
  } else if (style === 'ink-in-water') {
    const shade = Math.min(1, Math.max(0, (inten - 0.14) * 1.7 * expo));
    oR = 0.92 - shade * 0.80; oG = 0.90 - shade * 0.74; oB = 0.85 - shade * 0.50;
  } else if (style === 'neon') {
    const m = Math.pow(Math.min(1, inten * 1.05), 1.35);
    const c = pal(inten * 1.3 + (gg - rr) * 1.0 + T * 0.05, hb);
    const gl = m * expo * 1.6;
    oR = Math.min(1, c[0] * gl * 1.2); oG = Math.min(1, c[1] * gl * 1.2); oB = Math.min(1, c[2] * gl * 1.2);
  } else { // marbled-paint — vivid multi-hue pigment smear (exposure curve → rich mids, highlights roll off, never full white-out)
    oR = 1 - Math.exp(-rr * expo * 1.25);
    oG = 1 - Math.exp(-gg * expo * 1.25);
    oB = 1 - Math.exp(-bb * expo * 1.25);
  }
  const o = idx * 4;
  px[o] = oR * 255; px[o + 1] = oG * 255; px[o + 2] = oB * 255; px[o + 3] = 255;
}
g.updatePixels();

// commit swap (r2 becomes current)
S.r = r2; S.gc = g2; S.b = b2; S.r2 = r; S.g2 = gc; S.b2 = b;

push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();

// audio sparkle on top — partial ADD, never full-frame flash
if (A.treble > 0.02 || A.rms > 0.02) {
  push(); blendMode(ADD); noStroke();
  const glow = (A.treble * 0.5 + A.rms * 0.4) * P.energy;
  fill((hb + 40) % 360, 35, 100, Math.min(20, glow * 24));
  rect(0, 0, width, height);
  blendMode(BLEND); pop();
}
